CREATE TABLE IF NOT EXISTS billing_channel_settings (instance_id VARCHAR(64) NOT NULL,channel_id BIGINT NOT NULL,discount DECIMAL(8,4) NOT NULL DEFAULT 1,updated_at DATETIME(6) NOT NULL,updated_by VARCHAR(128) NOT NULL DEFAULT '',PRIMARY KEY(instance_id,channel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS billing_channel_hourly (job_id VARCHAR(40) NOT NULL,instance_id VARCHAR(64) NOT NULL,hour_start DATETIME NOT NULL,channel_id BIGINT NOT NULL,channel_name VARCHAR(128) NOT NULL DEFAULT '',model_name VARCHAR(255) NOT NULL,group_name VARCHAR(64) NOT NULL DEFAULT '',tier_from BIGINT NOT NULL DEFAULT 0,request_count BIGINT NOT NULL DEFAULT 0,prompt_tokens BIGINT NOT NULL DEFAULT 0,completion_tokens BIGINT NOT NULL DEFAULT 0,cache_tokens BIGINT NOT NULL DEFAULT 0,quota BIGINT NOT NULL DEFAULT 0,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(job_id,hour_start,channel_id,model_name,group_name,tier_from),KEY idx_billing_channel_hourly_finalize(instance_id,hour_start,channel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS billing_channel_daily_versions (job_id VARCHAR(40) NOT NULL,instance_id VARCHAR(64) NOT NULL,channel_id BIGINT NOT NULL,channel_name VARCHAR(128) NOT NULL DEFAULT '',model_name VARCHAR(255) NOT NULL,group_name VARCHAR(64) NOT NULL DEFAULT '',tier_from BIGINT NOT NULL DEFAULT 0,day DATE NOT NULL,request_count BIGINT NOT NULL DEFAULT 0,prompt_tokens BIGINT NOT NULL DEFAULT 0,completion_tokens BIGINT NOT NULL DEFAULT 0,cache_tokens BIGINT NOT NULL DEFAULT 0,quota BIGINT NOT NULL DEFAULT 0,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(job_id,channel_id,model_name,group_name,tier_from,day),KEY idx_billing_channel_report(instance_id,day,channel_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
